        You are a programming expert. 
        You will be provided with a patch used to fix a bug. 
        Based on the commit message and modifications in the patch, you need to analyze the root cause of the bug in detail. 

        Here is the patch content:
        From 5ec398183ee58ddbdcdda454b30ac9247b491783 Mon Sep 17 00:00:00 2001
From: Razvan Crainea <razvan@opensips.org>
Date: Thu, 19 Mar 2020 18:30:18 +0200
Subject: [PATCH] dialog: do not update topo hiding advertised contact

This commit fixes a bug introduced by commit 7b7a9fc2bf, that was
updating the contact *after* topology hiding has replaced it. This bug
would be triggered when a re-INVITE/UPDATE was triggered on a call that
had topology hiding enabled - in these scenarios OpenSIPS would re-learn
the contact advertised by topology hiding, that is OpenSIPS itself,
resulting in looped sequential requests.
---
 modules/dialog/dlg_handlers.c | 11 ++++++++++-
 1 file changed, 10 insertions(+), 1 deletion(-)

diff --git a/modules/dialog/dlg_handlers.c b/modules/dialog/dlg_handlers.c
index fd6937709..3b93d7ec6 100644
--- a/modules/dialog/dlg_handlers.c
+++ b/modules/dialog/dlg_handlers.c
@@ -1263,7 +1263,7 @@ out_free:
 static inline int dlg_update_contact(struct dlg_cell *dlg, struct sip_msg *msg,
 											unsigned int leg)
 {
-	str contact;
+	str contact, contact_hdr;
 	char *tmp;

 	if (!msg->contact &&
@@ -1275,6 +1275,15 @@ static inline int dlg_update_contact(struct dlg_cell *dlg, struct sip_msg *msg,
 		return 0;
 	}
 	contact = ((contact_body_t *)msg->contact->parsed)->contacts->uri;
+	contact_hdr.s = msg->contact->name.s;
+	contact_hdr.len = msg->contact->len;
+
+	if ((dlg->mod_flags & TOPOH_ONGOING) &&
+			str_strcmp(&dlg->legs[leg].adv_contact, &contact_hdr) == 0) {
+		LM_DBG("skip updating topo hiding advertised contact\n");
+		return 0;
+	}
+
 	if (dlg->legs[leg].contact.s) {
 		/* if the same contact, don't do anything */
 		if (dlg->legs[leg].contact.len == contact.len &&
